public class StudentSorterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<Student> list = new java.util.ArrayList<>();
        list.add(new Student("Zoe", 88));
        list.add(new Student("Amy", 72));
        list.add(new Student("Ben", 88));
        list.add(new Student("Cal", 65));
        list.add(new Student("Ada", 88));
        StudentSorter.sortByGradeThenName(list);
        check("full sorted order",
                "[Student[name=Cal, grade=65], Student[name=Amy, grade=72], Student[name=Ada, grade=88], Student[name=Ben, grade=88], Student[name=Zoe, grade=88]]",
                list.toString());
        check("lowest grade first", "Cal", list.get(0).name());
        check("ties broken alphabetically", "Ada", list.get(2).name());
        check("last element", "Zoe", list.get(4).name());
        java.util.List<Student> sameGrade = new java.util.ArrayList<>();
        sameGrade.add(new Student("Rae", 90));
        sameGrade.add(new Student("Ann", 90));
        sameGrade.add(new Student("Max", 90));
        StudentSorter.sortByGradeThenName(sameGrade);
        check("all same grade sorts by name",
                "[Student[name=Ann, grade=90], Student[name=Max, grade=90], Student[name=Rae, grade=90]]",
                sameGrade.toString());
        java.util.List<Student> one = new java.util.ArrayList<>();
        one.add(new Student("Solo", 50));
        StudentSorter.sortByGradeThenName(one);
        check("single element unchanged", "[Student[name=Solo, grade=50]]", one.toString());
        java.util.List<Student> none = new java.util.ArrayList<>();
        StudentSorter.sortByGradeThenName(none);
        check("empty list is safe", "[]", none.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

